import msal
import os

class IdentityClient:
    def __init__(self, client_id, tenant_id, client_secret, scope=None):
        self.client_id = client_id
        self.tenant_id = tenant_id
        self.client_secret = client_secret
        self.scope = scope or ["https://graph.microsoft.com/.default"]
        self.authority = f"https://login.microsoftonline.com/{self.tenant_id}"
        self.app = msal.ConfidentialClientApplication(
            self.client_id, authority=self.authority, client_credential=self.client_secret
        )

    def acquire_token_for_client(self):
        result = self.app.acquire_token_for_client(scopes=self.scope)
        if "access_token" not in result:
            raise RuntimeError("Failed to acquire token from Microsoft Identity Platform")
        return result["access_token"]

    def acquire_token_on_behalf_of(self, user_assertion, scopes=None):
        scopes = scopes or ["User.Read"]
        result = self.app.acquire_token_on_behalf_of(
            user_assertion=user_assertion, scopes=scopes
        )
        if "access_token" not in result:
            raise RuntimeError("Failed to acquire token on behalf of user")
        return result["access_token"]

import msal
import os

def email_password_login(payload, config=None):
    config = config or {}
    # PublicClientApplication is used for ROPC flow
    app = msal.PublicClientApplication(
        config['client_id'], authority=f"https://login.microsoftonline.com/{config['tenant_id']}"
    )

    # The ROPC flow is generally not recommended due to security implications.
    # This is for demonstration purposes as requested by the prompt for direct email/password login.
    result = app.acquire_token_by_username_password(
        username=payload['email'],
        password=payload['password'],
        scopes=config.get('scopes', ['User.Read'])
    )

    if "access_token" not in result:
        raise RuntimeError(f"Microsoft Identity Platform authentication failed: {result.get('error_description', 'Unknown error')}")

    return {
        'access_token': result['access_token'],
        'refresh_token': result.get('refresh_token'),
        'id_token': result.get('id_token'),
        'expires_in': result.get('expires_in')
    }
